"css": "\n.ys-btn { cursor: pointer; transition: transform 120ms cubic-bezier(0.16, 1, 0.3, 1), box-shadow 120ms cubic-bezier(0.16, 1, 0.3, 1), background-color 180ms cubic-bezier(0.16, 1, 0.3, 1), color 180ms cubic-bezier(0.16, 1, 0.3, 1); }\n.ys-btn:hover { background-color: var(--d10184c8-299f-44cc-9cc4-6c157ab82ff9); color: var(--61b9a0dd-bc66-4d7f-8665-a7ecc186a2b9); }\n.ys-btn:active { transform: translateY(2px); }\n.ys-btn:focus-visible { outline: 3px solid var(--d9039d0b-819d-46c0-955a-c724d9bf8417); outline-offset: 4px; }\n.ys-btn--primary:hover { background-color: var(--3c44f5ba-3123-4eec-8a2d-22b102237125); color: var(--d10184c8-299f-44cc-9cc4-6c157ab82ff9); }\n.ys-btn--primary:active { transform: translate(2px, 2px); box-shadow: 2px 2px 0 var(--d10184c8-299f-44cc-9cc4-6c157ab82ff9); }\n.ys-btn:disabled, .ys-btn[aria-disabled=\"true\"] { opacity: 0.55; cursor: not-allowed; transform: none; }\n@media (prefers-reduced-motion: reduce) { .ys-btn { transition: none; } }\n\n.ys-band-btn:hover { background-color: var(--d10184c8-299f-44cc-9cc4-6c157ab82ff9); color: var(--61b9a0dd-bc66-4d7f-8665-a7ecc186a2b9); }\n.ys-band-tel { transition: text-decoration-color 180ms cubic-bezier(0.16, 1, 0.3, 1); }\n.ys-band-tel:hover { text-decoration-color: var(--d9039d0b-819d-46c0-955a-c724d9bf8417); }\n.ys-band-tel:active { transform: translateY(1px); }\n.ys-band-tel:focus-visible { outline: 3px solid var(--d9039d0b-819d-46c0-955a-c724d9bf8417); outline-offset: 3px; }\n@media (prefers-reduced-motion: reduce) { .ys-band-tel { transition: none; } }\n",
"js": "\nconst live = typeof window !== \"undefined\";\nconst d = component_data || {};\nconst outs = Array.from(this.querySelectorAll(\".ys-hours\"));\nif (!live || !outs.length || !(d.hours || []).length) return;\nconst DAYS = [\"sun\", \"mon\", \"tue\", \"wed\", \"thu\", \"fri\", \"sat\"];\nconst NAMES = [\"Sunday\", \"Monday\", \"Tuesday\", \"Wednesday\", \"Thursday\", \"Friday\", \"Saturday\"];\nconst minutes = (s) => {\n  const m = /^(\\d{1,2})(?::?(\\d{2}))?$/.exec(String(s || \"\").trim());\n  return m ? Number(m[1]) * 60 + Number(m[2] || 0) : null;\n};\nconst clock = (mins) => {\n  const h = Math.floor(mins / 60) % 24;\n  const m = mins % 60;\n  if (h === 12 && !m) return \"noon\";\n  return (h % 12 || 12) + (m ? \":\" + String(m).padStart(2, \"0\") : \"\") + (h >= 12 ? \"pm\" : \"am\");\n};\nconst week = {};\nd.hours.forEach((row) => {\n  const i = DAYS.indexOf(String(row.day || \"\").slice(0, 3).toLowerCase());\n  if (i < 0) return;\n  const open = minutes(row.open);\n  const close = minutes(row.close);\n  week[i] = open !== null && close !== null && close > open ? { open: open, close: close } : null;\n});\nlet format;\ntry { format = new Intl.DateTimeFormat(\"en-US\", { timeZone: d.tz || undefined, weekday: \"short\", hour: \"2-digit\", minute: \"2-digit\", hourCycle: \"h23\" }); }\ncatch (error) { format = new Intl.DateTimeFormat(\"en-US\", { weekday: \"short\", hour: \"2-digit\", minute: \"2-digit\", hourCycle: \"h23\" }); }\nconst say = (sentence) => outs.forEach((out) => { out.textContent = sentence; });\nconst paint = () => {\n  try {\n    const parts = format.formatToParts(new Date());\n    const get = (type) => (parts.find((p) => p.type === type) || {}).value;\n    const day = DAYS.indexOf(String(get(\"weekday\")).slice(0, 3).toLowerCase());\n    const now = (Number(get(\"hour\")) % 24) * 60 + Number(get(\"minute\"));\n    if (day < 0) return;\n    const today = week[day];\n    if (today && now >= today.open && now < today.close) {\n      say(d.open_text + \" \" + clock(today.close) + \".\");\n      return;\n    }\n    for (let k = 0; k < 8; k++) {\n      const i = (day + k) % 7;\n      const slot = week[i];\n      if (!slot || (k === 0 && now >= slot.open)) continue;\n      const when = k === 0 ? \"today\" : k === 1 ? \"tomorrow\" : NAMES[i];\n      say(d.closed_text + \" \" + clock(slot.open) + \" \" + when + \".\");\n      return;\n    }\n  } catch (error) {\n    /* keep the written hours */\n  }\n};\npaint();\nconst timer = setInterval(paint, 60000);\nreturn () => clearInterval(timer);\n"
