def split_rows(raw):
	if isinstance(raw, str):
		try:
			raw = json.loads(raw)
		except Exception:
			raw = [raw]
	out = []
	for item in raw or []:
		parts = []
		for part in str(item).split("|"):
			parts.append(part.strip())
		if parts and parts[0]:
			out.append(parts)
	return out


def num(value):
	try:
		text = str(value).replace(",", "").replace("$", "").replace("%", "").strip()
		if not text:
			return None
		return float(text)
	except Exception:
		return None


def money(value, cur):
	digits = str(int(round(value)))
	out = ""
	while len(digits) > 3:
		out = "," + digits[-3:] + out
		digits = digits[:-3]
	return cur + digits + out


def slugify(text):
	out = ""
	for ch in str(text or "").lower():
		out = out + (ch if ch.isalnum() else "-")
	return out


def fixed(value):
	return str(round(value, 2))

hours = []
for parts in split_rows(props.get("hours")):
	hours.append({"day": parts[0], "open": parts[1] if len(parts) > 1 else "", "close": parts[2] if len(parts) > 2 else ""})
component.component_data = {
	"hours": hours,
	"tz": str(props.get("time_zone") or ""),
	"open_text": str(props.get("open_text") or ""),
	"closed_text": str(props.get("closed_text") or ""),
}
